import{_ as t,o as r,c as i,a4 as a}from"./chunks/framework.BybBnFXO.js";const p=JSON.parse('{"title":"Origin & Treatment Disclosure","description":"","frontmatter":{"title":"Origin & Treatment Disclosure","grading":"origin-disclosure"},"headers":[],"relativePath":"grading/origin-disclosure.md","filePath":"grading/origin-disclosure.md","lastUpdated":1785887013000}'),o={name:"grading/origin-disclosure.md"};function n(s,e,d,l,c,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="origin-treatment-disclosure" tabindex="-1">Origin &amp; Treatment Disclosure <a class="header-anchor" href="#origin-treatment-disclosure" aria-label="Permalink to &quot;Origin &amp; Treatment Disclosure&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Trade rules (CIBJO Blue Books; FTC Guides; AGTA Disclosure) require sellers to declare treatments and, when claimed, geographic origin. Common treatments are tier-ranked by their impact on value.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Untreated (&quot;No Indications of Treatment&quot;): top tier; requires a respected lab report.</li><li>Routine (e.g. heat on sapphire / ruby): widely accepted; <strong>must be disclosed</strong>.</li><li>Enhancement (oil/resin in emerald, dye, fracture filling): large value hit.</li><li>Origin opinion: based on inclusion suite + trace chemistry; only reputable labs.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Grade</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>heated (H)</td><td>routine — caps price</td></tr><tr><td>emerald</td><td>minor oil (Cedarwood)</td><td>accepted with disclosure</td></tr><tr><td>sapphire</td><td>unheated, Kashmir</td><td>5–10× price of heated</td></tr></tbody></table><p><em>See the <a href="./intro.html">grading overview</a>.</em></p>',8)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
